import duckdb,boto3,json,re
sess=boto3.Session(profile_name='scrapivo',region_name='us-east-2'); cr=sess.get_credentials().get_frozen_credentials(); s3=sess.client('s3'); gaz=json.loads(s3.get_object(Bucket='scrapivo-raw-data-2026-523220341033-us-east-2-an',Key='processed/gazetteer/gazetteer.json')['Body'].read())
