norm=lambda s:re.sub(r'[^a-z0-9]+',' ',s.lower()).strip(); keys=set(gaz.get('business_locality',{})); unmatched=[(loc,n) for loc,n in rows if norm(loc) not in keys]; out={'gazetteer_bytes':4683692,'locality_keys':len(keys),'country_keys':len(gaz.get('business_country',{})),'data_unique_localities':len(rows),'matched_unique':len(rows)-len(unmatched),'unmatched_unique':len(unmatched),'unmatched_rows':sum(n for _,n in unmatched),'unmatched_examples':[x[0] for x in sorted(unmatched,key=lambda x:x[1],reverse=True)[:30]]}; open('reports/gate2/_gazetteer-profile.json','w').write(json.dumps(out,indent=2)); print(json.dumps(out))